mapper.select:
SELECT period, status, COUNT(*) AS count FROM (
    SELECT  AS period, t.status AS status
    FROM tasks t
    WHERE t.is_deleted = false
      AND t.task_type != 'WBS_TASK'
      AND t.created_at >= #{from}
      AND t.created_at <= #{to}


          AND t.creator_id IN (
              SELECT id FROM users WHERE department_id IN

                  #{id}

          )


          AND t.creator_id = #{userId}



    UNION ALL

    SELECT  AS period, t.status AS status
    FROM tasks t
    JOIN task_assignees ta ON ta.task_id = t.id
    WHERE t.is_deleted = false
      AND t.task_type = 'WBS_TASK'
      AND t.created_at >= #{from}
      AND t.created_at <= #{to}


          AND ta.user_id IN (
              SELECT id FROM users WHERE department_id IN

                  #{id}

          )


          AND ta.user_id = #{userId}


) combined
GROUP BY period, status
ORDER BY period, status
